-- Modify "refunds" table
ALTER TABLE "payment"."refunds" ADD CONSTRAINT "refunds_topup_called_check" CHECK ((topup_external_id IS NULL) OR (topup_called_at IS NOT NULL)), ADD CONSTRAINT "refunds_topup_external_check" CHECK (((topup_status = 'DONE'::text) = (topup_external_id IS NOT NULL)) AND ((topup_external_id IS NULL) OR ((char_length(topup_external_id) >= 1) AND (char_length(topup_external_id) <= 255)))), ADD CONSTRAINT "refunds_topup_lookup_failures_check" CHECK (topup_lookup_failures >= 0), ADD CONSTRAINT "refunds_topup_only_failed_check" CHECK ((topup_status = 'NONE'::text) OR (status = 'FAILED'::text)), ADD CONSTRAINT "refunds_topup_reason_check" CHECK (((topup_status = ANY (ARRAY['RELEASED'::text, 'ANOMALY'::text])) = (topup_reason IS NOT NULL)) AND ((topup_reason IS NULL) OR ((char_length(topup_reason) >= 1) AND (char_length(topup_reason) <= 200)))), ADD CONSTRAINT "refunds_topup_status_check" CHECK (topup_status = ANY (ARRAY['NONE'::text, 'WAITING'::text, 'SENDING'::text, 'DONE'::text, 'RELEASED'::text, 'ANOMALY'::text])), ADD COLUMN "transfer_deducted" boolean NOT NULL DEFAULT false, ADD COLUMN "topup_status" text NOT NULL DEFAULT 'NONE', ADD COLUMN "topup_reason" text NULL, ADD COLUMN "topup_idempotency_key" uuid NOT NULL DEFAULT gen_random_uuid(), ADD COLUMN "topup_called_at" timestamptz NULL, ADD COLUMN "topup_external_id" text NULL, ADD COLUMN "topup_lookup_failures" integer NOT NULL DEFAULT 0;
-- Create index "refunds_topup_external" to table: "refunds"
CREATE UNIQUE INDEX "refunds_topup_external" ON "payment"."refunds" ("topup_external_id") WHERE (topup_external_id IS NOT NULL);
-- Create index "refunds_topup_sending" to table: "refunds"
CREATE INDEX "refunds_topup_sending" ON "payment"."refunds" ("updated_at", "id") WHERE (topup_status = 'SENDING'::text);
